391		for _, argv := range [][]string{{"--port", "abc"}, {"--port=abc"}, {"-pabc"}, {"--dur", "soon"}, {"--flag=maybe"}} {
392			_, err := p.Parse(argv)
393			if !errors.Is(err, ErrInvalidValue) {
394				t.Fatalf("%v: err = %v, want ErrInvalidValue", argv, err)
395			}
396			var pe *ParseError
397			if !errors.As(err, &pe) || pe.Name == "" || pe.Value == "" {
398				t.Fatalf("%v: invalid-value error must carry name and value, got %+v", argv, err)
399			}
400		}
401	
402		// Missing positional.
403		_, err := p.Parse([]string{"only-one"})
404		if !errors.Is(err, ErrRequired) {
405			t.Fatalf("err = %v, want ErrRequired", err)
406		}
407		var pe *ParseError
408		if !errors.As(err, &pe) || pe.Name != "second" {
409			t.Fatalf("missing positional error must carry %q, got %+v", "second", err)
410		}
411	
412		// Surplus positional.
413		_, err = p.Parse([]string{"a", "b", "c"})
414		if !errors.Is(err, ErrUnexpectedArgument) {
415			t.Fatalf("err = %v, want ErrUnexpectedArgument", err)
416		}
417		if !errors.As(err, &pe) || pe.Token != "c" {
418			t.Fatalf("surplus error must carry token %q, got %+v", "c", err)
419		}
420	
421		// Surplus positional after --.
422		_, err = p.Parse([]string{"a", "b", "--", "c"})
423		if !errors.Is(err, ErrUnexpectedArgument) {
424			t.Fatalf("err = %v, want ErrUnexpectedArgument", err)
425		}
