		return "command: invalid config value " + strconv.Quote(displayValue) + " for " + opt.ConfigKey + " " + strconv.Quote(opt.Long) + ": " + cause.Error()
	}
	return "command: invalid value " + strconv.Quote(displayValue) + " for option " + strconv.Quote(opt.Long) + ": " + cause.Error()
