package command

import (
	"reflect"
	"testing"
)

func TestEdgeRedactWaitingConsumesDashDash(t *testing.T) {
	// Parse treats the token after a waiting value option as its value,
	// even "--"; RedactArgs must match rather than switch to positional.
	p, _ := NewParser([]Option{
		{Long: "user", Short: "u", Type: TypeString},
		{Long: "token", Short: "t", Type: TypeString, Sensitive: true},
	}, nil)
	got := p.RedactArgs([]string{"--user", "--", "--token", "secret"})
	want := []string{"--user", "--", "--token", "<redacted>"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v want %v", got, want)
	}
	r, err := p.Parse([]string{"--user", "--", "--token", "secret"})
	if err != nil {
		t.Fatal(err)
	}
	if r.String("user") != "--" || r.String("token") != "secret" {
		t.Fatalf("parse semantics differ: user=%q token=%q", r.String("user"), r.String("token"))
	}
}
EOF
